import {lessons,plans,blueprint} from './content.js';
import {questions,byId,selectExam,examScore,questionScore} from './questions.js';
import {hex,bytes,gfMultiply,gfPower,SBOX,aesTrace,desSbox,DES_S1} from './crypto.js';
import {STORAGE_KEY,defaults,validateState,newExam,finishExam,latestGrades,reviewIds} from './store.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lesson=id=>lessons.find(l=>l.id===id);
const ico=(name,size=20)=>{const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M12 5c-4-3-8-1-9 0v15c3-2 6-2 9 0 3-2 6-2 9 0V5c-3-2-6-2-9 0z M12 5v15',calc:'M5 2h14v20H5z M8 6h8 M8 11h1 M15 11h1 M8 15h1 M15 15h1 M8 19h1 M15 19h1',exam:'M8 3H4v19h16V3h-4 M8 2h8v4H8z M8 11h8 M8 16h5',repeat:'M4 9a8 8 0 0 1 13-5l3 3 M20 2v5h-5 M20 15A8 8 0 0 1 7 20l-3-3 M4 22v-5h5',folder:'M3 6h7l2 3h9v11H3z M3 6V3h7l2 3h7v3',arrow:'M4 12h16 M14 6l6 6-6 6',check:'M5 12l4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',flag:'M5 22V3h14l-3 5 3 5H5',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',chevron:'m9 5 7 7-7 7',print:'M7 8V2h10v6 M7 17H3V8h18v9h-4 M7 14h10v8H7z'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;};
let state=defaults(),storageError='',query='',filter='all',reviewFilter='all',labTab='aes',trace=[],step=0;
try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)state=validateState(JSON.parse(raw));}catch{storageError='기존 저장 자료를 읽지 못했습니다. 원본 저장값은 새 기록을 저장하기 전까지 유지됩니다.';}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageError='';$('#save-state').innerHTML='<i></i> 이 브라우저에 저장';}catch{storageError='브라우저 저장 공간을 사용할 수 없습니다. 오답 노트에서 백업을 내려받으세요.';$('#save-state').textContent='저장 실패 · 백업 필요';toast(storageError);}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function go(path){if(location.hash===`#/${path}`)render();else location.hash=`#/${path}`;}
function path(){return location.hash.slice(2).split('/');}
const badge=(text,tone='purple')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const link=(href,text,cls='btn')=>`<a class="${cls}" href="#/${href}">${text}</a>`;
const btn=(action,text,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const heading=(eyebrow,title,desc,action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const progress=()=>Math.round(state.done.filter(id=>lesson(id)?.priority==='core').length/9*100);
const date=s=>new Date(s).toLocaleString('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
function sidebar(){const current=path()[0]||'home';const nav=[['home','grid','학습 대시보드'],['study','book','개념 공부'],['lab','calc','계산 연습실'],['exam','exam','모의고사'],['review','repeat','오답 노트']];$('#sidebar').innerHTML=`<a href="#/home" class="brand"><span class="brand-icon">${ico('book',25)}</span><span>시험 준비실<small>INFORMATION SECURITY</small></span></a><div class="space-label">나의 정보보호개론</div><nav aria-label="주 메뉴">${nav.map(([id,icon,title])=>`<a href="#/${id}" ${current===id||(id==='exam'&&current==='result')?'aria-current="page"':''}>${ico(icon)}<span>${title}</span>${id==='review'&&reviewIds(state).length?`<small>${reviewIds(state).length}</small>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-progress"><span>핵심 개념 학습 <b>${progress()}%</b></span><div class="track"><i style="width:${progress()}%"></i></div><small>${state.done.filter(id=>lesson(id)?.priority==='core').length} / 9개 핵심 단원 완료</small></div><div class="profile"><span>나</span><div>나만의 공부 공간<small>기록은 이 기기에 보관돼요</small></div></div></div>`;}
function roadmap(){return plans[state.plan].map((p,i)=>`<div class="plan-row"><div class="plan-number">${String(i+1).padStart(2,'0')}</div><div><small>${p.time}</small><h3>${p.title}</h3><p>${p.body}</p>${p.ids.length?`<div class="mini-links">${p.ids.map(id=>link(`study/${id}`,lesson(id).title,'')).join('')}</div>`:''}</div></div>`).join('');}
function dashboard(){const next=lesson(state.lastLesson)||lessons.find(l=>l.priority==='core'&&!state.done.includes(l.id))||lessons[0];const complete=state.history.filter(e=>examScore(e).graded===e.ids.length);const last=complete[0];return heading('A LITTLE EVERY DAY','오늘의 공부, 여기서 시작해요.','개념의 흐름을 잡고, 서술형 답안으로 이해를 확인하세요.',badge('2026 · 정보보호개론','neutral'))+`${state.active?`<div class="resume-banner">${ico('clock')} <span>작성 중인 ${state.active.ids.length}문항 모의고사가 있어요. ${state.active.deadline?'시험 시간은 계속 흐릅니다.':'답안이 저장되어 있어요.'}</span>${link('exam','이어서 풀기 →','text-link')}</div>`:''}<section class="hero"><div class="hero-copy"><span class="hero-kicker"><i></i> 이해에서 답안까지</span><h2>외우는 공부를 넘어,<br>설명할 수 있는 실력으로.</h2><p>핵심 개념과 계산 연습, 서술형 모의고사를<br class="desktop"> 하나의 학습 흐름으로 연결했어요.</p><div class="hero-actions">${link(`study/${next.id}`,`공부 ${state.lastLesson?'이어가기':'시작하기'} ${ico('arrow',17)}`,'btn white')}${link('exam','모의고사 풀기','hero-link')}</div></div><div class="hero-visual" aria-label="개념을 학습하고 답안을 작성한 뒤 복습하는 순환"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="floating-label label-one">${ico('check',15)} 개념 이해</div><div class="floating-label label-two">${ico('exam',15)} 서술형 연습</div><div class="hero-book"><div class="book-top">SECURITY<br><b>STUDY NOTES</b></div><div class="book-line"></div><div class="book-line short"></div><div class="book-symbol">{ <span>k</span> }</div><small>CONCEPT → PRACTICE</small></div><span class="dot-grid">····<br>····<br>····</span></div></section><div class="stats-grid"><div class="stat"><span class="stat-icon lavender">${ico('book')}</span><div><small>핵심 개념 진도</small><strong>${state.done.filter(id=>lesson(id)?.priority==='core').length}<em> / 9 단원</em></strong></div><div class="mini-ring" style="--value:${progress()}%"><span>${progress()}%</span></div></div><div class="stat"><span class="stat-icon green">${ico('exam')}</span><div><small>완료한 모의고사</small><strong>${state.history.length}<em> 회</em></strong></div><small class="stat-note">${last?`최근 자가채점 ${examScore(last).score}점`:'첫 실전을 기다리고 있어요'}</small></div><div class="stat"><span class="stat-icon peach">${ico('repeat')}</span><div><small>다시 볼 문제</small><strong>${reviewIds(state).length}<em> 문항</em></strong></div>${link('review','복습하기 →','text-link')}</div></div><div class="dashboard-columns"><section class="panel"><div class="section-heading"><div><h2>나에게 맞는 학습 플랜</h2><p>남은 시간에 맞춰, 중요한 것부터 차근차근.</p></div></div><div class="segments" aria-label="학습 계획 선택">${[['3h','시험 직전 3시간'],['3d','3일 집중'],['7d','7일 완성']].map(([id,t])=>btn('plan',t,state.plan===id?'selected':'',`data-id="${id}" aria-pressed="${state.plan===id}"`)).join('')}</div><div class="roadmap">${roadmap()}</div></section><div class="right-stack"><section class="exam-teaser"><div class="tiny-caps">PRACTICE MAKES PROGRESS</div><h2>백지에서 시작하는<br>서술형 모의고사</h2><div class="exam-facts"><span><b>21</b> 문항</span><span><b>60</b> 분 기본</span></div><p>직접 쓰고, 모범답안과 채점 기준을<br>대조하며 빠진 부분을 찾아보세요.</p>${link('exam',`실전 준비하기 ${ico('arrow',17)}`,'btn primary full')}<small>21문항 · 연습 시간 선택 가능</small></section><section class="note-card"><span class="note-pin">${ico('spark',19)}</span><h3>설명하면 더 오래 기억해요</h3><p>정의를 읽은 뒤 화면을 덮고 조건과 이유를 직접 말해 보세요. 막힌 부분은 오답 노트에 남겨 두세요.</p>${link('review','오답 노트 열기 →','text-link')}</section></div></div><div class="section-heading spaced"><div><h2>우선 챙겨야 할 네 가지</h2><p>정의와 조건을 익히고 계산으로 확인할 주제입니다.</p></div>${link('study','전체 개념 보기 →','text-link')}</div><div class="priority-grid">${['algebra','aes','hash','mac'].map(id=>{const l=lesson(id);return `<a href="#/study/${id}" class="priority-card"><div>${badge(l.tag)}<span>${l.num}</span></div><h3>${l.title}</h3><p>${l.subtitle}</p><small>${ico('clock',14)} ${l.minutes}분 <span>${state.done.includes(id)?'학습 완료 ✓':'학습하기 ↗'}</span></small></a>`;}).join('')}</div>`;}
function lessonCards(){const list=lessons.filter(l=>(filter==='all'||filter==='core'&&l.priority==='core'||filter==='supplement'&&l.priority==='supplement'||filter==='unfinished'&&!state.done.includes(l.id))&&`${l.title} ${l.subtitle} ${l.sections.map(s=>s.title+' '+s.body).join(' ')}`.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(l=>`<a href="#/study/${l.id}" class="lesson-card"><span class="lesson-number">${l.num}</span><div class="lesson-info"><div>${badge(l.tag,l.priority==='supplement'?'neutral':'purple')}${state.done.includes(l.id)?badge('학습 완료','green'):''}</div><h2>${l.title}</h2><p>${l.subtitle}</p></div><div class="lesson-end"><span>${ico('clock',15)} ${l.minutes}분</span>${ico('arrow')}</div></a>`).join(''):`<div class="empty">${ico('search',34)}<h2>검색 결과가 없어요</h2><p>다른 단어로 검색하거나 범위를 바꿔 보세요.</p></div>`;}
function study(id){if(!id)return heading('CONCEPT LIBRARY','개념을 이해하는 시간','정의 → 예시 → 직접 설명하기. 한 단원씩 내 것으로 만드세요.')+`<div class="study-toolbar"><label class="search-box">${ico('search')}<input id="lesson-search" type="search" placeholder="AES, 역원, 패딩… 개념 검색" aria-label="개념 검색" value="${esc(query)}"></label><div class="chips">${[['all','전체 11'],['core','핵심 9'],['supplement','보충 2'],['unfinished','아직 안 본 내용']].map(([id,t])=>btn('filter',t,filter===id?'chip active':'chip',`data-id="${id}" aria-pressed="${filter===id}"`)).join('')}</div></div><div id="lesson-list" class="lesson-list">${lessonCards()}</div>`;
 const l=lesson(id);if(!l)return notFound();state.lastLesson=l.id;save();return `<div class="back-row">${link('study','← 전체 개념','text-link')}<div>${btn('print',ico('print',16)+' 인쇄','btn small')}${badge(l.tag)}</div></div>`+heading(`CHAPTER ${l.num}`,l.title,l.subtitle)+`<div class="lesson-layout"><article class="lesson-body"><div class="learning-goal"><small>이 단원을 마치면</small><p>${l.outcome}</p><span>${ico('clock',14)} 약 ${l.minutes}분</span></div>${l.sections.map((s,i)=>`<section class="reading-section" id="section-${i}"><h2><span>${String(i+1).padStart(2,'0')}</span>${s.title}</h2>${s.body}</section>`).join('')}<section class="recall-box"><div class="eyebrow">CLOSE YOUR NOTES</div><h2>자료를 덮고, 설명해 보세요.</h2><ol>${l.recall.map(t=>`<li>${t}</li>`).join('')}</ol></section><div class="lesson-complete">${btn('complete',`${ico('check',18)} ${state.done.includes(id)?'학습 완료 표시 해제':'이 단원 학습 완료'}`,state.done.includes(id)?'btn secondary':'btn primary',`data-id="${id}"`)}${btn('topic-exam','이 단원 문제 풀기 →','btn',`data-id="${id}"`)}</div></article><aside class="lesson-toc"><h3>이 단원의 내용</h3>${l.sections.map((s,i)=>`<button data-action="section" data-id="${i}">${String(i+1).padStart(2,'0')} <span>${s.title}</span></button>`).join('')}<hr><p>답안에는 <b>정의·조건·이유</b>를 함께 담아 보세요.</p>${['aes','gf','des'].includes(id)?link('lab','계산 연습실 열기 ↗','text-link'):''}</aside></div>`;}
function resource(type){if(type==='des')return `<details class="resource"><summary>제공 자료 · DES S₁ 표</summary><div class="table-scroll"><table class="mono-table"><tr><th>행 / 열</th>${Array.from({length:16},(_,i)=>`<th>${i}</th>`).join('')}</tr>${DES_S1.map((r,i)=>`<tr><th>${i}</th>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</table></div></details>`;if(type==='aes')return `<details class="resource"><summary>제공 자료 · AES S-box와 MixColumns 행렬</summary><p>모든 값은 16진수입니다. S-box는 상위 4비트가 행, 하위 4비트가 열입니다.</p><div class="table-scroll"><table class="mono-table"><tr><th>행 / 열</th>${Array.from({length:16},(_,i)=>`<th>${i.toString(16)}</th>`).join('')}</tr>${Array.from({length:16},(_,r)=>`<tr><th>${r.toString(16)}</th>${SBOX.slice(r*16,r*16+16).map(x=>`<td>${hex([x])}</td>`).join('')}</tr>`).join('')}</table></div><pre>02 03 01 01\n01 02 03 01\n01 01 02 03\n03 01 01 02</pre><p>곱은 GF(2⁸), 합은 XOR. m(x)=x⁸+x⁴+x³+x+1.</p></details>`;return '';}
function matrix(state,label='상태'){return `<div class="matrix-wrap"><small>${label} · 열 우선 바이트</small><div class="matrix">${Array.from({length:16},(_,i)=>`<span>${hex([state[(i%4)*4+Math.floor(i/4)]])}</span>`).join('')}</div></div>`;}
function traceView(){if(!trace.length)return '';const s=trace[step];return `<div class="trace-card"><div class="trace-heading"><div><small>STEP ${String(step+1).padStart(2,'0')} / ${trace.length}</small><h2>${s.label}</h2></div><span>${badge(step===trace.length-1?'앞 2라운드 완료':'중간 상태','neutral')}</span></div><p>${s.detail}</p><div class="matrix-pair">${matrix(s.state)}${s.key?matrix(s.key,'이번 라운드키'):''}</div><code class="byte-string">${hex(s.state)}</code><div class="trace-controls">${btn('trace-prev','← 이전','btn',step===0?'disabled':'')}<span>${step+1} / ${trace.length}</span>${btn('trace-next','다음 단계 →','btn primary',step===trace.length-1?'disabled':'')}</div><div class="trace-dots">${trace.map((s,i)=>btn('trace-goto',String(i+1),i===step?'active':'',`data-id="${i}" title="${s.label}" aria-label="${s.label}" aria-pressed="${i===step}"`)).join('')}</div></div>`;}
function lab(){return heading('CALCULATION STUDIO','손으로 풀고, 단계별로 검산해요.','작은 예제로 연산을 익히고, 중간 상태를 비교해 실수를 찾아보세요.')+`<div class="tabs">${[['aes','AES 앞 2라운드'],['gf','GF(2⁸) 연산'],['des','DES S-box']].map(([id,t])=>btn('lab-tab',t,labTab===id?'active':'',`data-id="${id}" aria-pressed="${labTab===id}"`)).join('')}</div>`+(labTab==='aes'?`<div class="lab-layout"><section class="panel"><h2>AES-128 따라가기</h2><p class="muted">열 우선 상태, 초기 키 결합, 두 번의 일반 라운드를 확인합니다.</p><form id="aes-form"><label>평문 · 16바이트<input name="plain" class="mono" value="00112233445566778899aabbccddeeff" required spellcheck="false"></label><label>키 · 16바이트<input name="key" class="mono" value="000102030405060708090a0b0c0d0e0f" required spellcheck="false"></label><button class="btn primary full" type="submit">단계별 계산 시작 ${ico('arrow',17)}</button><p class="form-error" role="alert"></p></form><div class="tip"><b>먼저 종이에 계산해 보세요.</b><p>2라운드는 마지막 라운드가 아닙니다. 두 라운드 모두 MixColumns를 수행합니다.</p></div>${link('study/aes','AES 개념 다시 보기 →','text-link')}${resource('aes')}</section><section id="trace-output">${trace.length?traceView():`<div class="empty trace-empty"><span class="large-icon">${ico('calc',42)}</span><h2>한 단계씩 눈으로 확인하기</h2><p>예제 평문과 키가 입력되어 있어요.<br>계산을 시작하면 4×4 상태를 볼 수 있습니다.</p><div class="step-pills"><span>SubBytes</span><span>ShiftRows</span><span>MixColumns</span><span>AddRoundKey</span></div></div>`}</section></div>`:labTab==='gf'?`<div class="lab-layout"><section class="panel"><h2>바이트를 다항식으로</h2><p>기약다항식 x⁸+x⁴+x³+x+1을 사용하는 AES의 GF(2⁸)입니다.</p><form id="gf-form"><div class="two-fields"><label>바이트 a · 16진수<input name="a" value="57" maxlength="2" class="mono" required></label><label>바이트 b · 16진수<input name="b" value="13" maxlength="2" class="mono" required></label></div><button type="submit" class="btn primary">연산 확인하기</button><p class="form-error" role="alert"></p></form>${link('study/gf','갈루아체 개념 다시 보기 →','text-link')}</section><section id="gf-output" class="panel"><h2>곱셈과 덧셈은 다릅니다</h2><p>덧셈은 XOR, 곱셈은 다항식을 곱한 뒤 나머지를 구합니다. a=57, b=13의 곱은 fe입니다.</p></section></div>`:`<div class="lab-layout"><section class="panel"><h2>DES S₁ 테이블 읽기</h2><p>바깥 두 비트가 행, 안쪽 네 비트가 열입니다.</p><form id="des-form"><label>6비트 입력<input name="bits" value="100111" maxlength="6" class="mono" required></label><button type="submit" class="btn primary">행·열·출력 확인</button><p class="form-error" role="alert"></p></form>${link('study/des','DES 개념 다시 보기 →','text-link')}${resource('des')}</section><section id="des-output" class="panel"><h2>6비트에서 4비트로</h2><p>DES는 서로 다른 S-box 8개를 사용합니다. 이 실습은 그중 S₁을 다룹니다.</p></section></div>`);}
function examSetup(){return heading('WRITE. CHECK. REPEAT.','모의고사로 실력을 확인해요.','답안을 직접 쓴 뒤 모범답안과 기준별 자가채점으로 이해를 점검합니다.')+`<div class="exam-setup"><section class="panel"><div class="setup-title"><span class="large-icon">${ico('exam',29)}</span><div><h2>나의 실전 설정</h2><p>서술형 답안 작성과 계산을 함께 연습합니다.</p></div></div><form id="exam-form"><fieldset><legend>연습 방식</legend><label class="radio-card"><input type="radio" name="mode" value="full" checked><span><b>21문항 실전</b><small>핵심 9단원에서 균형 있게 21문항</small></span>${badge('추천')}</label><label class="radio-card"><input type="radio" name="mode" value="quick"><span><b>가볍게 점검</b><small>선택 범위에서 최대 5문항</small></span></label><label class="radio-card"><input type="radio" name="mode" value="topic"><span><b>단원 집중 연습</b><small>선택 범위에서 최대 10문항</small></span></label></fieldset><div class="two-fields"><label>집중 연습 범위<select name="topic" disabled><option value="all">전체 핵심 범위</option>${lessons.map(l=>`<option value="${l.id}">${l.title}${l.priority==='supplement'?' · 보충':''}</option>`).join('')}</select></label><label>연습 시간<select name="duration"><option value="60">60분</option><option value="30">30분</option><option value="90">90분</option><option value="0">시간 제한 없음</option></select></label></div><button class="btn primary full" type="submit">모의고사 시작 ${ico('arrow',18)}</button><p class="muted small-text">답안은 입력할 때마다 저장됩니다. 시간 제한은 다른 페이지나 탭으로 이동해도 계속 흐릅니다.</p></form></section><aside class="right-stack"><section class="panel blueprint"><h3>21문항 구성</h3><p>핵심 9단원의 개념과 계산을 고르게 점검합니다.</p>${Object.entries(blueprint).map(([id,n])=>`<div><span>${lesson(id).title}</span><b>${n}</b></div>`).join('')}</section><div class="note-card"><h3>채점은 어떻게 하나요?</h3><p>제출 후 모범답안과 비교해 충족한 기준에 체크합니다. 모든 문항의 비중은 같고, 문항 안의 기준도 같은 비중입니다.</p><p>서술형 의미를 자동 판정하지 않습니다. 점수는 자가점검용이며 실제 시험 배점·예측 점수가 아닙니다.</p></div></aside></div>`+historyPanel();}
function remaining(e){if(!e.deadline)return '시간 제한 없음';const sec=Math.max(0,Math.ceil((e.deadline-Date.now())/1000));return `${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`;}
function examPage(){const e=state.active;if(!e)return examSetup();const q=byId[e.ids[e.index]],answered=e.ids.filter(id=>e.answers[id]?.trim()).length;return `<div class="exam-top"><div><div class="eyebrow">PRACTICE IN PROGRESS</div><h1>${esc(e.mode)}</h1></div><div class="timer ${e.deadline&&e.deadline-Date.now()<300000?'urgent':''}">${ico('clock')}<b id="timer">${remaining(e)}</b></div></div><div class="exam-layout"><section class="answer-card"><div class="question-meta"><span>문항 ${String(e.index+1).padStart(2,'0')} <small>/ ${e.ids.length}</small></span><div>${badge(lesson(q.lesson).title,'neutral')}${badge(q.type)}</div></div><h2>${esc(q.title)}</h2><p class="question-prompt">${esc(q.prompt)}</p>${resource(q.resource)}<label class="answer-label" for="answer-input">나의 답안 <small>정의, 과정, 이유를 함께 적어 보세요.</small></label><textarea id="answer-input" name="answer" maxlength="12000" placeholder="여기에 답안을 작성하세요. 계산 문제는 풀이 과정도 함께 남겨 주세요." rows="12">${esc(e.answers[q.id]||'')}</textarea><div class="answer-status"><span id="answer-count">${(e.answers[q.id]||'').length}자</span><span id="answer-saved">입력 즉시 자동 저장</span></div><div class="question-actions">${btn('flag',ico('flag',16)+(e.flags.includes(q.id)?' 다시 볼 표시 해제':' 다시 볼 문제'),e.flags.includes(q.id)?'btn flagged':'btn',`data-id="${q.id}" aria-pressed="${e.flags.includes(q.id)}"`)}<div>${btn('prev','← 이전','btn',e.index===0?'disabled':'')}${btn('next','다음 →','btn primary',e.index===e.ids.length-1?'disabled':'')}</div></div></section><aside class="exam-nav panel"><h3>답안 현황 <span id="answered">${answered} / ${e.ids.length}</span></h3><div class="question-grid">${e.ids.map((id,i)=>`<button data-action="question" data-id="${i}" class="${e.index===i?'current ':''}${e.answers[id]?.trim()?'answered ':''}${e.flags.includes(id)?'flagged':''}" aria-label="${i+1}번 문제${e.answers[id]?.trim()?', 답안 작성됨':''}${e.flags.includes(id)?', 다시 볼 표시':''}" ${e.index===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><div class="legend"><span><i class="filled"></i>작성함</span><span><i class="flagged"></i>다시 보기</span></div>${btn('submit',`답안 제출하기 ${ico('check',17)}`,'btn primary full')}<p class="small-text muted">빈 답안은 0점 처리됩니다. 제출하면 모범답안과 채점 기준이 열립니다.</p>${link('home','저장한 채로 나가기 →','text-link')}${btn('discard','이번 시험 삭제','text-button danger')}</aside></div>`;}
function gradeContent(e,id,index){const q=byId[id],grade=e.grades[id],score=questionScore(q,grade);return `<article class="graded-question" id="graded-${id}"><div class="question-meta"><span>문항 ${String(index+1).padStart(2,'0')}</span><div>${badge(lesson(q.lesson).title,'neutral')}${btn('bookmark',ico('star',16),state.bookmarks.includes(id)?'icon-btn starred':'icon-btn',`data-id="${id}" aria-label="${state.bookmarks.includes(id)?'북마크 해제':'북마크 추가'}" aria-pressed="${state.bookmarks.includes(id)}"`)}</div></div><h2>${esc(q.title)}</h2><p class="question-prompt">${esc(q.prompt)}</p><div class="submitted-answer"><small>나의 답안</small><p>${esc(e.answers[id]?.trim()||'작성하지 않은 답안입니다.')}</p></div><div class="model-answer"><small>모범답안 · 표현이 달라도 논리가 같으면 인정</small><p>${esc(q.answer)}</p></div><div class="pitfall"><b>놓치기 쉬운 부분</b> ${esc(q.pitfall)}</div><div class="rubric"><div class="rubric-heading"><h3>내 답안에서 충족한 기준</h3><span id="qscore-${id}" class="badge ${score===null?'neutral':score===1?'green':'orange'}">${score===null?'채점 전':`${Math.round(score*100)}% 충족`}</span></div><p>각 기준은 이 문항에서 같은 비중입니다. 읽고 이해한 내용이 아니라, 제출한 답안에 쓴 내용을 체크하세요.</p>${q.rubric.map((r,i)=>`<label class="criterion"><input type="checkbox" data-grade="${i}" data-exam="${e.id}" data-question="${id}" ${grade?.[i]?'checked':''} ${!e.answers[id]?.trim()?'disabled':''}><span>${esc(r)}</span></label>`).join('')}<div class="grade-actions">${btn('grade-all','모든 기준 충족','btn small',`data-exam="${e.id}" data-id="${id}" ${!e.answers[id]?.trim()?'disabled':''}`)}${btn('grade-none','충족한 기준 없음 · 0점','btn small',`data-exam="${e.id}" data-id="${id}"`)}</div></div><div class="related-concept">${link(`study/${q.lesson}`,'관련 개념 복습 →','text-link')}</div><label class="note-label">나의 복습 메모<textarea data-note="${id}" maxlength="3000" rows="2" placeholder="빠뜨린 조건이나 다음에 기억할 한 문장">${esc(state.notes[id]||'')}</textarea></label></article>`;}
function resultSummary(e){const s=examScore(e);return `<div class="result-summary"><div><div class="eyebrow">${e.timedOut?'시간 종료로 자동 제출':'답안 제출 완료'}</div><h1>${s.graded===s.total?'나의 이해도를 확인했어요.':'채점 기준으로 답안을 점검해요.'}</h1><p>${date(e.finished)} · ${e.ids.length}문항 · ${Math.max(0,Math.round((e.finished-e.started)/60000))}분 경과</p></div><div class="score-block"><b>${s.graded===s.total?s.score:'—'}<small> / 100</small></b><span>${s.graded} / ${s.total}문항 자가채점${s.graded<s.total?' · 미채점 문항을 확인하세요':''}</span></div></div>`;}
function resultPage(id){const e=state.history.find(x=>x.id===id);if(!e)return notFound();return `<div class="back-row">${link('exam','← 시험 기록','text-link')}${btn('print',ico('print',16)+' 답안 인쇄','btn small')}</div><div id="result-summary">${resultSummary(e)}</div><div class="result-toolbar"><p>모든 문항은 동일 비중 · 실제 시험 배점과 무관한 자가점검 점수입니다.</p>${btn('retry-result','부족한 문제 다시 풀기','btn primary',`data-id="${e.id}"`)}</div><div class="result-list">${e.ids.map((id,i)=>gradeContent(e,id,i)).join('')}</div>`;}
function reviewPage(){const all=reviewIds(state),latest=latestGrades(state.history);const ids=all.filter(id=>reviewFilter==='all'||reviewFilter==='bookmarked'?reviewFilter==='all'||state.bookmarks.includes(id):byId[id].lesson===reviewFilter);const pending=state.history.filter(e=>examScore(e).graded<e.ids.length);return heading('MAKE IT YOURS','틀린 문제에서 한 번 더 배워요.','최근 채점에서 놓친 문항과 북마크한 문항을 모았습니다.',btn('retry-review',`이 목록 다시 풀기 ${ico('arrow',17)}`,'btn primary',ids.length?'':'disabled'))+`${pending.length?`<div class="resume-banner">${ico('exam')}<span>자가채점을 마치지 않은 시험이 ${pending.length}개 있어요.</span>${link(`result/${pending[0].id}`,'채점 이어가기 →','text-link')}</div>`:''}<div class="study-toolbar"><div class="chips">${[['all',`전체 ${all.length}`],['bookmarked',`북마크 ${state.bookmarks.length}`]].map(([id,t])=>btn('review-filter',t,reviewFilter===id?'chip active':'chip',`data-id="${id}"`)).join('')}</div><label class="inline-select">단원<select id="review-topic"><option value="all">전체 단원</option>${lessons.map(l=>`<option value="${l.id}" ${reviewFilter===l.id?'selected':''}>${l.title}</option>`).join('')}</select></label></div>${ids.length?`<div class="review-list">${ids.map(id=>{const q=byId[id],item=latest[id];return `<article class="review-card"><div class="question-meta"><div>${badge(lesson(q.lesson).title,'neutral')}${item?badge(`${Math.round(item.score*100)}% 충족`,item.score===1?'green':'orange'):badge('북마크','purple')}</div>${btn('bookmark',ico('star',18),state.bookmarks.includes(id)?'icon-btn starred':'icon-btn',`data-id="${id}" aria-label="${state.bookmarks.includes(id)?'북마크 해제':'북마크 추가'}"`)}</div><h2>${esc(q.title)}</h2><p>${esc(q.prompt)}</p><details><summary>답안과 놓치기 쉬운 부분 확인</summary><div class="model-answer"><p>${esc(q.answer)}</p></div><p>${esc(q.pitfall)}</p>${item?`<div class="submitted-answer"><small>최근 채점한 나의 답안</small><p>${esc(item.exam.answers[id]||'미작성')}</p></div>`:''}</details><label class="note-label">복습 메모<textarea data-note="${id}" maxlength="3000" rows="2" placeholder="다음에 기억할 한 문장">${esc(state.notes[id]||'')}</textarea></label><div class="review-actions">${link(`study/${q.lesson}`,'개념 다시 보기','text-link')}${btn('retry-one','이 문제 다시 풀기 →','btn small',`data-id="${id}"`)}</div></article>`;}).join('')}</div>`:`<div class="empty panel">${ico('check',42)}<h2>아직 다시 볼 문제가 없어요.</h2><p>모의고사를 풀고 채점하면 부족한 문항이 여기에 모입니다.<br>문항의 별표를 눌러 따로 저장할 수도 있어요.</p>${link('exam','모의고사 시작하기','btn primary')}</div>`}`+backupPanel();}
function historyPanel(){return `<section class="panel spaced"><div class="section-heading"><div><h2>나의 시험 기록</h2><p>최근 20회 보관 · 점수는 기준별 자가채점 결과</p></div></div>${state.history.length?`<div class="history-list">${state.history.map(e=>{const s=examScore(e);return `<a href="#/result/${e.id}"><div><b>${esc(e.mode)}</b><small>${date(e.finished)} · ${e.ids.length}문항</small></div><span>${s.graded===s.total?`<b>${s.score}</b>점`:`${s.graded}/${s.total} 채점`}</span>${ico('chevron',18)}</a>`;}).join('')}</div>`:'<p class="muted">아직 제출한 시험이 없습니다. 첫 모의고사를 시작해 보세요.</p>'}</section>`;}
function backupPanel(){return `<section class="panel spaced"><h2>학습 기록 보관하기</h2><p>학습 진도, 답안, 자가채점, 북마크와 메모는 이 브라우저의 저장소에만 남습니다. 다른 기기로 옮기거나 브라우저 데이터를 지우기 전에 백업하세요.</p><div class="backup-actions">${btn('export',ico('download',17)+' 백업 내려받기','btn primary')}<label class="btn import-label">백업 가져오기<input type="file" id="import-file" accept=".json,application/json"></label>${btn('reset','학습 기록 초기화','btn danger')}</div><p class="small-text muted">가져오기는 현재 기록을 백업 내용으로 바꿉니다. 파일 검증 후 교체 여부를 확인합니다.</p></section>`;}
function notFound(){return `<div class="empty panel"><h1>페이지를 찾을 수 없어요.</h1>${link('home','대시보드로 돌아가기','btn primary')}</div>`;}
function render(){let [page,id]=path();page||='home';const labels={home:'학습 대시보드',study:'개념 공부',lab:'계산 연습실',exam:'모의고사',result:'모의고사 결과',review:'오답 노트'};sidebar();$('#page-label').textContent=labels[page]||'페이지';document.title=`${labels[page]||'시험 준비실'} · 정보보호개론`;$('#main').innerHTML=(storageError?`<div class="alert" role="alert">${esc(storageError)}</div>`:'')+({home:dashboard,study:()=>study(id),lab,exam:examPage,result:()=>resultPage(id),review:reviewPage}[page]||notFound)();}
function confirmAction(title,body,label,action){const d=$('#confirm-dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(body)}</p><div class="dialog-actions"><button class="btn" id="dialog-cancel">취소</button><button class="btn primary" id="dialog-ok">${esc(label)}</button></div>`;$('#dialog-cancel').onclick=()=>d.close();$('#dialog-ok').onclick=()=>{d.close();action();};d.showModal();$('#dialog-cancel').focus();}
function start(ids,duration,mode){const run=()=>{state.active=newExam(ids,duration,mode);save();go('exam');};if(state.active)confirmAction('진행 중인 시험을 바꿀까요?','새 시험을 시작하면 아직 제출하지 않은 현재 답안이 삭제됩니다.','새 시험 시작',run);else run();}
function submit(timedOut=false){if(!state.active)return;const e=finishExam(state.active,Date.now(),timedOut);state.history.unshift(e);state.history=state.history.slice(0,20);state.active=null;save();go(`result/${e.id}`);if(timedOut)toast('시간이 끝나 저장된 답안을 자동 제출했습니다.');}
function refreshGrade(e,id){save();const summary=$('#result-summary');if(summary)summary.innerHTML=resultSummary(e);const span=$(`#qscore-${id}`);if(span){const s=questionScore(byId[id],e.grades[id]);span.textContent=`${Math.round(s*100)}% 충족`;span.className=`badge ${s===1?'green':'orange'}`;}document.querySelectorAll(`[data-question="${id}"]`).forEach((x,i)=>x.checked=e.grades[id][i]);sidebar();}
function filteredReview(){return reviewIds(state).filter(id=>reviewFilter==='all'||(reviewFilter==='bookmarked'?state.bookmarks.includes(id):byId[id].lesson===reviewFilter));}
document.addEventListener('click',ev=>{
 if(ev.target.closest('.skip')){ev.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return;}
 const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;const e=state.active;
 if(a==='plan'){state.plan=id;save();render();}
 if(a==='filter'){filter=id;render();}
 if(a==='complete'){state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];save();render();toast(state.done.includes(id)?'학습 완료로 표시했어요.':'완료 표시를 해제했어요.');}
 if(a==='section')$(`#section-${id}`)?.scrollIntoView({behavior:'smooth',block:'start'});
 if(a==='topic-exam')start(selectExam('topic',id),0,`${lesson(id).title} 집중 연습`);
 if(a==='lab-tab'){labTab=id;render();}
 if(a==='trace-prev'||a==='trace-next'||a==='trace-goto'){step=a==='trace-goto'?Number(id):step+(a==='trace-next'?1:-1);step=Math.max(0,Math.min(trace.length-1,step));$('#trace-output').innerHTML=traceView();}
 if(a==='next'||a==='prev'||a==='question'){if(!e)return;e.index=a==='question'?Number(id):e.index+(a==='next'?1:-1);save();render();$('#main').scrollIntoView({block:'start'});$('#answer-input')?.focus({preventScroll:true});}
 if(a==='flag'){if(!e)return;e.flags=e.flags.includes(id)?e.flags.filter(x=>x!==id):[...e.flags,id];save();render();}
 if(a==='submit'){if(!e)return;const blank=e.ids.filter(id=>!e.answers[id]?.trim()).length;confirmAction('답안을 제출할까요?',`${e.ids.length}문항 중 ${blank}문항이 미작성입니다. 제출 후 모범답안이 공개되고 작성한 답안은 수정할 수 없습니다.`,'제출하고 채점하기',()=>submit());}
 if(a==='discard')confirmAction('진행 중인 시험을 삭제할까요?','현재 작성한 답안이 삭제됩니다. 이미 제출한 시험 기록은 유지됩니다.','삭제',()=>{state.active=null;save();render();});
 if(a==='bookmark'){state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();if(path()[0]==='review')render();else{b.classList.toggle('starred',state.bookmarks.includes(id));b.setAttribute('aria-pressed',state.bookmarks.includes(id));b.setAttribute('aria-label',state.bookmarks.includes(id)?'북마크 해제':'북마크 추가');sidebar();}}
 if(a==='grade-all'||a==='grade-none'){const record=state.history.find(x=>x.id===b.dataset.exam);if(!record)return;record.grades[id]=byId[id].rubric.map(()=>a==='grade-all');refreshGrade(record,id);}
 if(a==='retry-result'){const record=state.history.find(x=>x.id===id);const ids=record.ids.filter(q=>questionScore(byId[q],record.grades[q])!==null&&questionScore(byId[q],record.grades[q])<1);if(!ids.length){toast('먼저 자가채점을 완료하거나 부족한 기준을 표시해 주세요.');return;}start(ids,0,'부족한 문항 재시험');}
 if(a==='review-filter'){reviewFilter=id;render();}
 if(a==='retry-review')start(filteredReview(),0,'오답·북마크 재시험');
 if(a==='retry-one')start([id],0,'한 문제 다시 풀기');
 if(a==='print')window.print();
 if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`infosec-study-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('학습 기록을 백업 파일로 내려받았습니다.');}
 if(a==='reset')confirmAction('모든 학습 기록을 초기화할까요?','학습 진도, 진행 중 답안, 시험 기록, 북마크, 메모가 모두 삭제됩니다. 필요한 기록은 먼저 백업하세요.','모두 초기화',()=>{state=defaults();save();render();toast('학습 기록을 초기화했습니다.');});
});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='lesson-search'){query=el.value;$('#lesson-list').innerHTML=lessonCards();}
 if(el.id==='answer-input'&&state.active){const e=state.active,id=e.ids[e.index];e.answers[id]=el.value;save();$('#answer-count').textContent=`${el.value.length}자`;$('#answer-saved').textContent=storageError?'저장 실패 · 백업 필요':'저장됨';$('#answered').textContent=`${e.ids.filter(id=>e.answers[id]?.trim()).length} / ${e.ids.length}`;const nb=document.querySelector(`[data-action="question"][data-id="${e.index}"]`);nb?.classList.toggle('answered',!!el.value.trim());if(nb)nb.setAttribute('aria-label',`${e.index+1}번 문제${el.value.trim()?', 답안 작성됨':''}${e.flags.includes(id)?', 다시 볼 표시':''}`);}
 if(el.dataset.note){state.notes[el.dataset.note]=el.value;save();}
});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.name==='mode')$('#exam-form select[name="topic"]').disabled=el.value==='full';
 if(el.dataset.grade!==undefined){const e=state.history.find(x=>x.id===el.dataset.exam),id=el.dataset.question;if(!e)return;e.grades[id]||=byId[id].rubric.map(()=>false);e.grades[id][Number(el.dataset.grade)]=el.checked;refreshGrade(e,id);}
 if(el.id==='review-topic'){reviewFilter=el.value;render();}
 if(el.id==='import-file'){try{const file=el.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('백업 파일은 10MB 이하여야 합니다.');const incoming=validateState(JSON.parse(await file.text()));confirmAction('백업 기록으로 바꿀까요?',`학습 완료 ${incoming.done.length}단원, 시험 ${incoming.history.length}회, 북마크 ${incoming.bookmarks.length}문항을 가져옵니다. 현재 기록을 교체합니다.`,'기록 가져오기',()=>{state=incoming;save();render();checkTimer();toast('백업 기록을 가져왔습니다.');});}catch(err){toast(`가져오기 실패: ${err.message}`);}el.value='';}
});
const polynomial=n=>{if(n===0)return '0';return Array.from({length:8},(_,i)=>7-i).filter(i=>n&(1<<i)).map(i=>i===0?'1':i===1?'x':`x^${i}`).join(' + ');};
document.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target,data=new FormData(f);try{
 if(f.id==='exam-form'){const mode=data.get('mode'),topic=data.get('topic')||'all';start(selectExam(mode,topic),Number(data.get('duration')),mode==='full'?'21문항 실전 모의고사':mode==='quick'?'5문항 빠른 점검':topic==='all'?'핵심 단원 집중 연습':`${lesson(topic).title} 집중 연습`);}
 if(f.id==='aes-form'){trace=aesTrace(bytes(data.get('plain'),16),bytes(data.get('key'),16));step=0;$('#trace-output').innerHTML=traceView();}
 if(f.id==='gf-form'){const a=bytes(data.get('a'),1)[0],b=bytes(data.get('b'),1)[0];const terms=[];for(let i=0;i<8;i++)if(b&(1<<i)){const product=gfMultiply(a,1<<i);terms.push(`${hex([a])} × x^${i} → ${hex([product])}`);}$('#gf-output').innerHTML=`<h2>연산 결과</h2><p class="mono">a = ${esc(polynomial(a))}<br>b = ${esc(polynomial(b))}</p><div class="calc-result"><small>덧셈 · XOR</small><b>${hex([a])} ⊕ ${hex([b])} = ${hex([a^b])}</b></div><div class="calc-result"><small>곱셈 · m(x)로 나눈 나머지</small><b>${hex([a])} × ${hex([b])} = ${hex([gfMultiply(a,b)])}</b></div><h3>b의 각 항에 따른 곱</h3><pre>${terms.length?terms.join('\n'):'b가 0이므로 곱은 0입니다.'}</pre><p>위 나머지를 모두 XOR하면 최종 곱입니다.</p><p>a의 곱셈 역원: <b>${a===0?'0은 곱셈 역원이 없습니다.':hex([gfPower(a,254)])}</b></p>`;}
 if(f.id==='des-form'){const bits=data.get('bits'),r=desSbox(bits);$('#des-output').innerHTML=`<h2>행 ${r.row}, 열 ${r.col}</h2><div class="bit-view"><strong>${bits[0]}</strong><span>${bits.slice(1,5)}</span><strong>${bits[5]}</strong></div><p>행: ${bits[0]+bits[5]}₂ = ${r.row}<br>열: ${bits.slice(1,5)}₂ = ${r.col}</p><div class="calc-result"><small>S₁[${r.row}][${r.col}] = ${r.value}</small><b>${r.value.toString(2).padStart(4,'0')}</b><span>4비트 출력</span></div>`;}
 f.querySelector('.form-error')?.replaceChildren();
 }catch(err){const msg=f.querySelector('.form-error');if(msg)msg.textContent=err.message;else toast(err.message);}
});
function checkTimer(){if(!state.active)return;const e=state.active;if(e.deadline&&Date.now()>=e.deadline){const dialog=$('#confirm-dialog');if(dialog.open)dialog.close();submit(true);return;}if($('#timer')){$('#timer').textContent=remaining(e);$('#timer').parentElement.classList.toggle('urgent',!!e.deadline&&e.deadline-Date.now()<300000);}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});checkTimer();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkTimer();});
window.addEventListener('storage',ev=>{if(ev.key===STORAGE_KEY&&ev.newValue){try{state=validateState(JSON.parse(ev.newValue));render();checkTimer();toast('다른 탭의 최신 학습 기록을 반영했습니다.');}catch{toast('다른 탭의 기록 형식을 읽을 수 없습니다.');}}});
render();checkTimer();setInterval(checkTimer,1000);
